using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.ML;
using Microsoft.ML;
using Microsoft.ML.Data;
using TicketClassifier.Models;
using TicketClassifier.Services;

namespace TicketClassifier.Controllers;

[ApiController]
[Route("api/[controller]")]
public sealed class TicketsController : ControllerBase
{
    private readonly PredictionEnginePool<TicketInput, TicketPrediction> _predictionPool;
    private readonly ModelTrainerService _trainer;

    public TicketsController(
        PredictionEnginePool<TicketInput, TicketPrediction> predictionPool,
        ModelTrainerService trainer)
    {
        _predictionPool = predictionPool;
        _trainer = trainer;
    }

    /// <summary>Predict the category for a support ticket.</summary>
    [HttpPost("classify")]
    public ActionResult<TicketResponse> Classify([FromBody] TicketRequest request)
    {
        var input = new TicketInput
        {
            Subject = request.Subject,
            Description = request.Description,
            Priority = request.Priority
        };

        var prediction = _predictionPool.Predict(input);

        // Extract label names in the order the model assigned keys
        var labels = GetLabelNames();

        var confidence = new Dictionary<string, float>();
        for (var i = 0; i < labels.Length && i < prediction.Score.Length; i++)
            confidence[labels[i]] = prediction.Score[i];

        return Ok(new TicketResponse
        {
            PredictedCategory = prediction.Category,
            Confidence = confidence
        });
    }

    /// <summary>Re-train the model and return evaluation metrics.</summary>
    [HttpPost("train")]
    public ActionResult<TrainingMetrics> Train()
    {
        var metrics = _trainer.TrainAndSave();
        return Ok(metrics);
    }

    private string[] GetLabelNames()
    {
        var engine = _predictionPool.GetPredictionEngine();
        var schema = engine.OutputSchema;
        var scoreColumn = schema.GetColumnOrNull("Score");
        if (scoreColumn is null) return ["Billing", "General", "Technical"];

        var slotNames = new VBuffer<ReadOnlyMemory<char>>();
        scoreColumn.Value.GetSlotNames(ref slotNames);

        return slotNames.DenseValues()
            .Select(v => v.ToString())
            .ToArray();
    }
}

